155: 
156:         JsonNode results = root.path("results");
157:         sb.append("针对'").append(query).append("'的搜索结果（共").append(results.size()).append("）条：\n");
158:         for (int i = 0; i < results.size(); i++) {
159:             JsonNode item = results.get(i);
160:             // 逐条输出：序列号+标题+链接+截断后的摘要
161:             sb.append(i + 1).append(". ").append(item.path("title").asText("无标题")).append("\n");
162:             sb.append(" 链接：").append(item.path("url").asText("")).append("\n");
163:             sb.append(" 摘要：").append(truncate(item.path("content").asText(""), MAX_CONTENT_LENGTH)).append("\n\n");
164:         }
165: 
166:         return sb.toString();
167:     }
168: 
169:     /** 超过长度上限的文本截断并加省略号，防止上下文被撑爆 */
170:     private String truncate(String text, int maxLength) {
171:         if (text == null || text.length() <= maxLength) {
172:             return text == null ? "" : text;
173:         }
174:         return text.substring(0, maxLength) + "……";
175:     }
