15: @Slf4j
16: @Component
17: @RequiredArgsConstructor
18: public class JevToolCapabilityRouter implements ToolCapabilityRouter {
19: 
20:     /**
21:      * 允许发送给 Jev 的最大 Java 字符数，用于限制隐私暴露范围与调用成本。
22:      */
23:     private static final int MAX_INPUT_CHARS = 4_000;
24: 
25:     /** properties：按轮次读取用户级 TypeSafe 配置。 */
26:     private final TypeSafeProperties properties;
27: 
28:     /** capabilityCatalog：提供允许交给 Jev 判断的能力组及说明。 */
29:     private final ToolCapabilityCatalog capabilityCatalog;
30: 
31:     /** gateway：负责调用 TypeSafe System One API。 */
32:     private final SystemOneGateway gateway;
33: 
34:     /**
35:      * 为一次新用户轮次生成 Tool 能力组决策
36:      *
37:      * @param request 当前用户文本和运行时可用能力组集合
38:      * @return 当前轮次的 Tool 能力组路由决策
39:      */
40:     @Override
41:     public ToolRoutingDecision route(ToolRoutingRequest request) {
42:         // 单调时钟起点，只用于计算路由耗时，不代表墙上时间
43:         long startedAt = System.nanoTime();
44: 
45:         try {
46:             // 本次路由开始时读取到的 TypeSafe 配置快照
47:             TypeSafeConfigData config = properties.load();
48:             if (!config.isReady()) return ToolRoutingDecision.off();
49: 
50:             // 去除首尾空白并执行长度限制后的 Jev 输入文本
51:             String state = normalizeInput(request.userInput());
52: 
53:             // 以能力组名为 key、一次性发送给 Jev 的全部 Noul 问题
54:             Map<String, JevNoulQuestion> questions = capabilityCatalog.capabilities()
55:                     .stream()
56:                     .filter(item -> request.availableGroups().contains(item.name()))
57:                     .collect(Collectors.toUnmodifiableMap(
58:                             ToolCapabilityCatalog.Capability::name,
59:                             item -> JevNoulQuestion.of(
60:                                     "完成当前用户请求是否需要以下能力：" + item.description()
61:                             )
62:                     ));
63: 
64:             // System One 对全部能力组问题返回的原始结构化响应
65:             JevSystemOneResponse response = gateway.evaluate(
66:                     config.apiKey(), config.model(), state, questions
67:             );
68: 
69:             // 校验完成以后，以能力组名为 key 的 yes 概率
70:             Map<String, Double> probabilities = validateAnswers(questions, response);
71: 
72:             // 概率达到配置阈值、准备暴露给主模型的能力组
73:             Set<String> selected = probabilities.entrySet().stream()
74:                     .filter(entry -> entry.getValue() >= config.threshold())
75:                     .map(Map.Entry::getKey)
76:                     .collect(Collectors.toUnmodifiableSet());
77: 
78:             // 决定结果只用于观测，还是立即应用于本轮 Model Call
79:             ToolRoutingDecision.Status status = config.mode() == ToolRoutingMode.ACTIVE
80:                     ? ToolRoutingDecision.Status.ACTIVE
81:                     : ToolRoutingDecision.Status.SHADOW;
82: 
83:             // 准备写入 RuntimeContext 的本轮最终路由决策
84:             ToolRoutingDecision decision = new ToolRoutingDecision(
85:                     status,
86:                     selected,
87:                     probabilities,
88:                     response.model(),
89:                     elapsedMillis(startedAt)
90:             );
91: 
92:             log.info("Jev Tool 路由完成： status={}, groups={}, probabilities={}, costMs={}",
93:                     decision.status(), decision.selectedGroups(), decision.probabilities(), decision.durationMillis());
94: 
95:             return decision;
96:         } catch (RuntimeException exception) {
97:             long duration = elapsedMillis(startedAt);
98:             ToolRoutingFailure failure = exception instanceof JevGatewayException gatewayException
99:                     ? gatewayException.failure()
100:                     : ToolRoutingFailure.unknown();
101:             log.warn("Jev Tool 路由失败，回退原有 Schema 流程：costMs={}, code={}, httpStatus={}, requestId={}",
102:                     duration,
103:                     failure.code(),
104:                     failure.httpStatus(),
105:                     failure.requestId());
106:             return ToolRoutingDecision.fallback(duration, failure);
107:         }
108:     }
109: 
110:     /**
111:      * 校验 Jev 是否为每个问题返回合法的 Noul 概率。
112:      *
113:      * @param questions 本次实际发出的能力组问题
114:      * @param response System One 返回的响应体
115:      * @return 以能力组名为键的不可变概率 Map
116:      * @throws JevGatewayException answers 缺失、类型错误或概率越界时抛出
117:      */
118:     private Map<String, Double> validateAnswers(
119:             Map<String, JevNoulQuestion> questions,
120:             JevSystemOneResponse response
121:     ) {
122:         if (response.answers() == null) {
123:             throw new JevGatewayException("TypeSafe 响应缺少 answers");
124:         }
125: 
126:         // probabilities：按问题遍历顺序暂存已经校验通过的能力组概率。
127:         Map<String, Double> probabilities = new LinkedHashMap<>();
128: 
129:         // group：questions 中当前正在校验的能力组名称。
130:         for (String group : questions.keySet()) {
131:             // answer：TypeSafe 为当前能力组返回的 Noul 答案。
132:             JevNoulAnswer answer = response.answers().get(group);
133:             if (answer == null || !"noul".equals(answer.type()) || answer.noul() == null) {
134:                 throw new JevGatewayException("TypeSafe 响应缺少有效 Noul 答案");
135:             }
136:             if (!Double.isFinite(answer.noul())
137:                     || answer.noul() < 0.0
138:                     || answer.noul() > 1.0) {
139:                 throw new JevGatewayException("TypeSafe Noul 概率超出范围");
140:             }
141:             probabilities.put(group, answer.noul());
142:         }
143:         return Map.copyOf(probabilities);
144:     }
145: 
