85:   const proactive = isUser ? false : isProactiveTranscriptMessage(dto, userTurnIds ?? allMessages);
86:   const parsedTime = dto.createdAt ? new Date(dto.createdAt).getTime() : NaN;
87:   const createdAt = Number.isFinite(parsedTime) && parsedTime > 0
88:     ? parsedTime
89:     : (proactive ? 0 : Date.now());
90:   const images: ChatImageAttachment[] | undefined = isUser
91:     ? dto.imageFileIds?.map((fileId, idx) => ({
