102:         dataUrl: '',
103:       }));
104:   return {
105:     id: dto.id,
106:     turnId: dto.turnId,
107:     role: isUser ? 'user' : 'assistant',
108:     modelName: isUser ? undefined : 'ButvanAgent',
109:     content: dto.content || '',
110:     images,
111:     reasoning: dto.thinking || undefined,
112:     createdAt,
113:     status: dto.status,
114:     usage: dto.usage,
115:     proactive: proactive || undefined,
116:     elapsedTime:
117:       dto.durationMillis != null
118:         ? Math.max(1, Math.round(dto.durationMillis / 1000))
119:         : undefined,
120:     tools:
121:       dto.tools && dto.tools.length > 0
122:         ? dto.tools.map(mapToolExecution)
123:         : undefined,
124:     blocks: isUser ? undefined : mapTranscriptBlocks(dto.id, dto.blocks),
125:   };
126: }
