32: fn image_extension(bytes: &[u8]) -> Option<&'static str> {
33:     if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
34:         Some("png")
35:     } else if bytes.starts_with(&[0xff, 0xd8, 0xff]) {
36:         Some("jpg")
37:     } else if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
38:         Some("gif")
39:     } else if bytes.starts_with(b"RIFF") && bytes.get(8..12) == Some(b"WEBP") {
40:         Some("webp")
41:     } else {
42:         None
43:     }
44: }

