import butvan.agent.network.material.web.*;
import butvan.agent.agents.tool.impl.*;
import butvan.agent.agents.config.*;
import java.lang.reflect.*;

public class TestDl {
    public static void main(String[] args) throws Exception {
        var tavily = new WebSearchTool(new TavilyProperties());
        var imgs = tavily.findImages("big tree landscape", 6);
        System.out.println("Found " + imgs.size() + " images");
        var cls = Class.forName("butvan.agent.network.material.web.PublicImageDownloader");
        var ctor = cls.getDeclaredConstructor();
        ctor.setAccessible(true);
        var dl = ctor.newInstance();
        var m = cls.getDeclaredMethod("download", String.class);
        m.setAccessible(true);
        for (var r : imgs) {
            try {
                var res = m.invoke(dl, r.url());
                System.out.println("OK: " + r.url() + " -> " + res);
            } catch (InvocationTargetException e) {
                System.out.println("FAIL: " + r.url() + " -> " + e.getCause());
                e.getCause().printStackTrace(System.out);
            }
        }
        System.exit(0);
    }
}
EOF
